CRUS = [
("l-clisson", "Clisson", "2011", "Granite", "A medieval town with Italianate architecture at the meeting of the Sèvre and the Moine, rebuilt after the Vendée wars. The cru communal Clisson, on coarse granite, gives broad, powerful Muscadet with long ageing on the lees."),
("l-gorges", "Gorges", "2011", "Gabbro and quartz", "Gorges sits on gabbro, a dark igneous rock rich in iron and magnesium, and its wines are tight, smoky and long-lived. It is one of the three original crus communaux of 2011."),
("l-le-pallet", "Le Pallet", "2011", "Gneiss and gabbro", "The birthplace of the philosopher Peter Abelard (1079), now one of the original crus communaux, on gneiss and gabbro. Its wines are fine and supple with a smoky note."),
("l-chateau-thebaud", "Château-Thébaud", "2019", "Granite", "A cru communal on the steep slopes of the Maine river, recognised in 2019. Its granite gives taut, saline wines with a firm, almost tannic grip after long lees ageing."),
("l-monnieres", "Monnières-Saint-Fiacre", "2019", "Gneiss and schist", "A cru communal recognised in 2019 on the slopes of the Sèvre, on gneiss and schist, making elegant, mineral wines that need several years to open."),
("l-mouzillon", "Mouzillon-Tillières", "2019", "Gabbro and granite", "A cru communal recognised in 2019 on the eastern side of the appellation, around the villages of Mouzillon and Tillières, mostly on gabbro, making full-bodied, structured Muscadet that ages well."),
("l-vallet", "Vallet", "proposed", "Schist and gneiss", "The self-styled capital of Muscadet, at the centre of the Sèvre et Maine vineyard. Vallet was one of three crus communaux put to INAO public consultation in 2025 and still awaiting final approval in 2026."),
("l-la-haie-fouassiere", "La Haie-Fouassière", "proposed", "Gneiss and amphibolite", "A village on the Sèvre, home of the Maison des Vins de Nantes, proposed as a cru communal in 2025 and still under INAO review in 2026."),
("l-champtoceaux", "Champtoceaux", "proposed", "Schist and gneiss", "A clifftop village above the Loire on the border of Anjou, proposed as the first cru communal of Muscadet Coteaux de la Loire in 2025, still under INAO review in 2026."),
]
for k, n, yr, rock, t in CRUS:
    cls = f"Muscadet cru communal ({yr})" if yr != 'proposed' else "Proposed Muscadet cru communal (INAO consultation 2025)"
    app = "Muscadet Coteaux de la Loire" if k == 'l-champtoceaux' else "Muscadet Sèvre et Maine"
    sites.append(S("loire-cru-" + slug(n), k, n, "cru", cls, app, t, None, q='approx'))

dump('loire', regions, apps, sites)
